dict.string:
/usr/bin/python3 - "$1" "$2" <<'PYEOF' import json, os, re, sys
query = " ".join(sys.argv[1:]).strip() default_repo = (os.environ.get("DEFAULT_REPO") or "").strip().strip("/")
def out(items): print(json.dumps({"items": items})) sys.exit(0)
def hint(title, subtitle): out([{"title": title, "subtitle": subtitle, "valid": False}])
if "/" not in default_repo: hint("Default repository is not set correctly", "Open this workflow's Configuration in Alfred and set it to owner/repo (e.g. sfcompute/sfcompute)")
default_org = default_repo.split("/", 1)[0]
parts = query.split() if not parts: hint("Open a GitHub pull request", "gh <number> [<repo>] — defaults to %s" % default_repo)
number = parts[0].lstrip("#") if not number.isdigit(): hint("'%s' is not a pull request number" % parts[0], "gh <number> [<repo>] — defaults to %s" % default_repo)
if len(parts) == 1: repo = default_repo source = "default repository" else: given = parts[1].strip("/") segments = [s for s in given.split("/") if s] if len(segments) == 1: repo = "%s/%s" % (default_org, segments[0]) source = "default organization %s" % default_org elif len(segments) == 2: repo = "/".join(segments) source = "explicit repository" else: hint("'%s' is not a valid repository" % parts[1], "Use <repo> or <owner>/<repo>")
if not re.fullmatch(r"[A-Za-z0-9._-]+/[A-Za-z0-9._-]+", repo): hint("'%s' is not a valid repository" % repo, "Use <repo> or <owner>/<repo>")
url = "https://github.com/%s/pull/%s" % (repo, number)
out([{ "uid": "%s#%s" % (repo, number), "title": "%s #%s" % (repo, number), "subtitle": "%s — %s" % (url, source), "arg": url, "quicklookurl": url, "text": {"copy": url, "largetype": url}, "mods": { "cmd": {"arg": url + "/files", "subtitle": "Open the Files changed tab"}, "alt": {"arg": "https://github.com/%s/pulls" % repo, "subtitle": "Open all pull requests for %s" % repo}, }, }]) PYEOF
